#!/usr/bin/env node
/**
 * OS-2543: Generates src/lib/bazi-knowledge-content.ts from docs/bazi-knowledge.md.
 *
 * Why: the app reads the BaZi knowledge base at runtime, but the Next.js
 * `output: 'standalone'` build (see Dockerfile runner stage) does NOT ship the
 * docs/ directory. Embedding the markdown as a generated TS module guarantees
 * it is bundled with the server code in every environment.
 *
 * Run automatically in the Dockerfile before `next build` (and via `npm run build`).
 * Do not edit the generated file by hand — edit docs/bazi-knowledge.md and re-run.
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const src = join(root, 'docs', 'bazi-knowledge.md')
const dest = join(root, 'src', 'lib', 'bazi-knowledge-content.ts')

const md = readFileSync(src, 'utf8')
const sectionCount = (md.match(/^## SECTION: /gm) || []).length
if (sectionCount < 7) {
  console.error(`[gen-bazi-knowledge] ERROR: expected >=7 "## SECTION:" headers in ${src}, found ${sectionCount}`)
  process.exit(1)
}

const out = `// AUTO-GENERATED by scripts/generate-bazi-knowledge.mjs from docs/bazi-knowledge.md.
// Do not edit by hand — edit the markdown and re-run the script (the Docker build runs it).
/* eslint-disable */
export const BAZI_KNOWLEDGE_MD: string = ${JSON.stringify(md)}
`
writeFileSync(dest, out)
console.log(`[gen-bazi-knowledge] wrote ${dest} (${out.length} bytes, ${sectionCount} sections)`)
